/**
 * The shape of the translation catalogue (catalog.ts, generated by
 * scripts/translate-catalog.mjs).
 *
 * PURE: types only.
 */

import type { ModelFile } from "../downloads/model-manifest";

/** How a model's matrices are stored, as Bergamot's `gemm-precision` names it. */
export type GemmPrecision = "int8shiftAll" | "int8shiftAlphaAll";

/** A file as the catalogue stores it: name, path under `MODELS_URL`, bytes, sha256. */
export type CompactFile = readonly [string, string, number, string];

/** A pair as the catalogue stores it: from, to, version, intgemm8 (1) or alphas (0), files. */
export type CompactPair = readonly [string, string, string, 0 | 1, readonly CompactFile[]];

/** One one-way language model ("nl" → "en"). */
export interface TranslationPair {
  /** BCP 47 codes as Firefox has them ("nl", "zh-Hans"). */
  from: string;
  to: string;
  version: string;
  precision: GemmPrecision;
  /**
   * `model.bin` first, then `vocab.spm` (or `srcvocab.spm` and
   * `trgvocab.spm`), then `lex.bin` when the model has a shortlist.
   */
  files: readonly ModelFile[];
}
